def eq_length(u, v, default_ConsNull=list):
    """Ensure two sequences have the same length and type."""
    return mapo(vararg_success, u, v, null_type=default_ConsNull)


def reduceo(relation, in_term, out_term, *args, **kwargs):
    """Relate a term and its fixed-point under a given relation."""
    def reduceo_goal(s):
        in_term_rf, out_term_rf = reify((in_term, out_term), s)

        term_rdcd = var()
        is_expanding = isvar(in_term_rf)

        single_apply_g = relation(in_term_rf, term_rdcd, *args, **kwargs)
        single_res_g = eq(term_rdcd, out_term_rf)

        def reduceo_rec(s):
            yield from reduceo(relation, term_rdcd, out_term_rf, *args, **kwargs)(s)

        if is_expanding:
            g = conde(
                [single_res_g],
                [Zzz(reduceo_rec)],
                [single_apply_g],
            )
        else:
            g = conde(
                [single_apply_g, Zzz(reduceo_rec)],
                [single_res_g],
            )

        yield from g(s)

    return reduceo_goal


def walko(goal, graph_in, graph_out, rator_goal=None, null_type=etuple, map_rel=partial(map_anyo, null_res=True)):
    """Apply a relation to all nodes in two graphs."""
    def walko_goal(s):
        graph_in_rf, graph_out_rf = reify((graph_in, graph_out), s)

        rator_in, rands_in, rator_out, rands_out = var(), var(), var(), var()

        def walko_rec(s):
            yield from map_rel(
                partial(walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel),
                rands_in,
                rands_out,
                null_type=null_type,
            )(s)

        g = conde(
            [goal(graph_in_rf, graph_out_rf)],
            [
                lall(
                    applyo(rator_in, rands_in, graph_in_rf),
                    applyo(rator_out, rands_out, graph_out_rf),
                    rator_goal(rator_in, rator_out),
                    Zzz(walko_rec),
                ) if rator_goal is not None else Zzz(lambda s: map_rel(
                    partial(walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel),
                    graph_in_rf,
                    graph_out_rf,
                    null_type=null_type,
                )(s)),
            ],
        )

        yield from g(s)

    return walko_goal


def term_walko(
    rator_goal,
    rands_goal,
    a,
    b,
    null_type=etuple,
    no_ident=False,
    format_step=None,
    **kwargs
):
    """Recursively walk a term graph and apply logic goals."""
    def single_step(s, t):
        u, v = var(), var()
        u_rator, u_rands = var(), var()
        v_rands = var()

        def rands_goal_rec(s):
            yield from rands_goal(u_rands, v_rands, u_rator, **kwargs)(s)

        return lall(
            ground_order((s, t), (u, v)),
            applyo(u_rator, u_rands, u),
            applyo(u_rator, v_rands, v),
            rator_goal(u_rator),
            conso(var(), var(), u_rands),
            conso(var(), var(), v_rands),
            Zzz(rands_goal_rec),
        )

    def term_walko_step(s, t):
        u, v = var(), var()
        z, w = var(), var()

        def term_walko_rec(s):
            yield from map_anyo(term_walko_step, w, z, null_type=null_type)(s)

        return lall(
            ground_order((s, t), (u, v)),
            format_step(u, w) if format_step is not None else eq(u, w),
            conde(
                [single_step(w, v)],
                [
                    Zzz(term_walko_rec),
                    conde([eq(z, v)], [single_step(z, v)]),
                ],
            ),
        )

    return lall(
        term_walko_step(a, b)
        if no_ident
        else conde([term_walko_step(a, b)], [eq(a, b)]),
    )

from functools import partial

from unification import var, isvar
from unification import reify

from etuples import etuple

from .core import eq, conde, lall, succeed, Zzz, fail, ground_order
from .goals import conso, nullo
from .term import applyo


def mapo(relation, a, b, null_type=list, null_res=True, first=True):
    """Apply a relation to corresponding elements in two sequences and succeed if the relation succeeds for all pairs."""
    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    def mapo_rec(s):
        yield from mapo(relation, a_cdr, b_cdr, null_type=null_type, first=False)(s)

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (not first or null_res) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            relation(a_car, b_car),
            Zzz(mapo_rec),
        ],
    )


def map_anyo(relation, a, b, null_type=list, null_res=False, first=True, any_succeed=False):
    """Apply a relation to corresponding elements in two sequences and succeed if at least one pair succeeds."""
    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    def map_anyo_rec(s):
        yield from map_anyo(relation, a_cdr, b_cdr, null_type=null_type, any_succeed=any_succeed, first=False)(s)

    return conde(
        [
            nullo(a, b, default_ConsNull=null_type)
            if (any_succeed or (first and null_res))
            else fail
        ],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [relation(a_car, b_car), Zzz(map_anyo_rec)],
                [eq(a_car, b_car), Zzz(map_anyo_rec)],
            ),
        ],
    )


